package br.com.vitaflow.fhirfacade.traducao;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

@DisplayName("Normalizacao de telefone para E.164")
class TelefoneNormalizadoTest {

    @Nested
    @DisplayName("os cinco formatos que convivem na base de homologacao")
    class FormatosDaBase {

        @ParameterizedTest(name = "{0} -> {1}")
        @CsvSource({
                "'(71)22769309',      +557122769309",
                "'7125706473',        +557125706473",
                "'(71) 3119-8500',    +557131198500",
                "'71-2208-1233',      +557122081233",
                "'+55 71 924465777',  +5571924465777"
        })
        void normalizaTodosParaOMesmoPadrao(String bruto, String esperado) {
            assertThat(TelefoneNormalizado.paraE164(bruto)).isEqualTo(esperado);
        }
    }

    @Nested
    @DisplayName("as contagens de digitos presentes na base")
    class ContagensDeDigitos {

        @Test
        @DisplayName("11 digitos: celular nacional, recebe o codigo do Brasil")
        void onzeDigitos() {
            assertThat(TelefoneNormalizado.paraE164("71924465777")).isEqualTo("+5571924465777");
        }

        @Test
        @DisplayName("10 digitos: fixo nacional, recebe o codigo do Brasil")
        void dezDigitos() {
            assertThat(TelefoneNormalizado.paraE164("7131198500")).isEqualTo("+557131198500");
        }

        @Test
        @DisplayName("12 digitos: ja traz o 55, so ganha o sinal de mais")
        void dozeDigitos() {
            assertThat(TelefoneNormalizado.paraE164("557131198500")).isEqualTo("+557131198500");
        }

        @Test
        @DisplayName("13 digitos: ja traz o 55, so ganha o sinal de mais")
        void trezeDigitos() {
            assertThat(TelefoneNormalizado.paraE164("5571924465777")).isEqualTo("+5571924465777");
        }
    }

    @Nested
    @DisplayName("quando nao da para inferir, a fachada nao inventa prefixo")
    class SemInferencia {

        @ParameterizedTest
        @ValueSource(strings = {"123", "999999999", "12345678901234", "abc", ""})
        void devolveNuloParaOChamadorUsarOValorDeOrigem(String bruto) {
            assertThat(TelefoneNormalizado.paraE164(bruto)).isNull();
        }

        @Test
        @DisplayName("12 ou 13 digitos que nao comecam com 55 nao viram numero brasileiro")
        void naoAssumeBrasilParaCodigoDeOutroPais() {
            assertThat(TelefoneNormalizado.paraE164("351912345678")).isNull();
        }

        @Test
        void toleraNulo() {
            assertThat(TelefoneNormalizado.paraE164(null)).isNull();
        }
    }
}

