/**
 * Os SEIS formatos de telefone continuam presentes.
 *
 * <p>Existe porque um levantamento anterior agrupou formatos distintos
 * num mesmo balde e contou cinco, escondendo o formato "DDD espaco
 * numero-hifen". Cada formato aqui e um caso que a normalizacao E.164
 * precisa cobrir; se algum sumir da base, o teste correspondente em
 * TelefoneNormalizadoTest deixa de proteger alguma coisa real.
 */
@Test
@DisplayName("os 6 formatos de telefone continuam existindo na base")
void formatosDeTelefone() {
    var porFormato = leitura.queryForList("""
            SELECT CASE
                     WHEN ds_contato ~ '@'                              THEN 'e-mail'
                     WHEN ds_contato ~ '^\\+55 '                         THEN 'com-ddi'
                     WHEN ds_contato ~ '^\\([0-9]{2}\\) [0-9]+-[0-9]+$'   THEN 'parenteses-espaco'
                     WHEN ds_contato ~ '^\\([0-9]{2}\\)[0-9]+$'           THEN 'parenteses-colado'
                     WHEN ds_contato ~ '^[0-9]{2}-[0-9]+-[0-9]+$'       THEN 'ddd-hifen'
                     WHEN ds_contato ~ '^[0-9]{2} [0-9]+-[0-9]+$'       THEN 'ddd-espaco'
                     WHEN ds_contato ~ '^[0-9]+$'                       THEN 'so-digitos'
                     ELSE 'NAO CLASSIFICADO' END AS formato,
                   count(*) AS quantos
              FROM sigh.paciente_contato
             GROUP BY 1
            """).stream()
            .collect(java.util.stream.Collectors.toMap(
                    l -> (String) l.get("formato"), l -> (Long) l.get("quantos")));

    assertThat(porFormato).containsOnlyKeys(
            "so-digitos", "ddd-espaco", "parenteses-colado",
            "parenteses-espaco", "ddd-hifen", "com-ddi", "e-mail");

    assertThat(porFormato).containsEntry("so-digitos", 81L)
            .containsEntry("ddd-espaco", 57L)
            .containsEntry("parenteses-colado", 50L)
            .containsEntry("parenteses-espaco", 48L)
            .containsEntry("ddd-hifen", 45L)
            .containsEntry("com-ddi", 40L)
            .containsEntry("e-mail", 54L);
}

@Test
@DisplayName("todo telefone da base e normalizavel para E.164")
void todoTelefoneNormaliza() {
    var naoNormalizaveis = leitura.queryForList(
                    "SELECT ds_contato FROM sigh.paciente_contato WHERE tp_contato <> 'EML'",
                    String.class)
            .stream()
            .filter(bruto -> br.com.vitaflow.fhirfacade.traducao.TelefoneNormalizado
                    .paraE164(bruto) == null)
            .toList();

    assertThat(naoNormalizaveis)
            .as("telefones que sairiam como texto bruto no recurso")
            .isEmpty();
}

