package br.com.vitaflow.fhirfacade.contrato;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.apoio.SighPostgres;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

/**
 * O seguro contra o acoplamento assumido em DA-01.
 *
 * <p>A fachada depende do modelo de dados da Medsys, e nao de um contrato de
 * API. Uma atualizacao do SIGH pode mudar coluna sem aviso — e o dicionario de
 * dados do fornecedor ja provou nao ser fonte confiavel: declara sete colunas
 * como obrigatorias que nao sao NOT NULL no DDL real.
 *
 * <p>Estes testes devem rodar a cada atualizacao do SIGH.
 */
@DisplayName("Contrato com o schema do fornecedor")
class ContratoDoSchemaIT {

    private static JdbcTemplate leitura;
    private static JdbcTemplate proprietario;

    /** Colunas que a fachada le. nm_mae nao esta aqui — PD-03. */
    private static final Map<String, Map<String, String>> COLUNAS_ESPERADAS = Map.of(
            "paciente", Map.of(
                    "cd_paciente", "integer",
                    "nm_paciente", "character varying",
                    "nm_social", "character varying",
                    "dt_nascimento", "date",
                    "tp_sexo", "character",
                    "nr_cpf", "character varying",
                    "nr_cns", "character varying",
                    "st_ativo", "character",
                    "dt_obito", "date",
                    "dt_atualizacao", "timestamp without time zone"),
            "paciente_contato", Map.of(
                    "cd_contato", "integer",
                    "cd_paciente", "integer",
                    "tp_contato", "character",
                    "ds_contato", "character varying",
                    "st_principal", "character"),
            "paciente_endereco", Map.of(
                    "cd_endereco", "integer",
                    "cd_paciente", "integer",
                    "ds_logradouro", "character varying",
                    "nm_bairro", "character varying",
                    "cd_municipio_ibge", "integer",
                    "sg_uf", "character",
                    "nr_cep", "character varying",
                    "st_principal", "character"),
            "municipio_ibge", Map.of(
                    "cd_municipio_ibge", "integer",
                    "nm_municipio", "character varying",
                    "sg_uf", "character"));

    /** Valores de dominio que o codigo da fachada sabe traduzir. */
    private static final Map<String, Set<String>> DOMINIOS_CONHECIDOS = Map.of(
            "SEXO", Set.of("M", "F", "I"),
            "TP_CONTATO", Set.of("RES", "CEL", "COM", "EML"),
            "ST_ATIVO", Set.of("S", "N"));

    @BeforeAll
    static void conectar() {
        leitura = jdbc("integracao_ro", "integracao_ro");
        proprietario = jdbc("sigh_app", "sigh_app");
    }

    private static JdbcTemplate jdbc(String usuario, String senha) {
        var fonte = new DriverManagerDataSource(
                SighPostgres.homologacao().getJdbcUrl(), usuario, senha);
        fonte.setDriverClassName("org.postgresql.Driver");
        return new JdbcTemplate(fonte);
    }

    /** Devolve as colunas esperadas que estao faltando ou com tipo trocado. */
    private static List<String> divergencias(JdbcTemplate jdbc, String schema) {
        var problemas = new java.util.ArrayList<String>();
        COLUNAS_ESPERADAS.forEach((tabela, colunas) -> colunas.forEach((coluna, tipo) -> {
            var encontrado = jdbc.queryForList("""
                    SELECT data_type FROM information_schema.columns
                     WHERE table_schema = ? AND table_name = ? AND column_name = ?
                    """, String.class, schema, tabela, coluna);
            if (encontrado.isEmpty()) {
                problemas.add(schema + "." + tabela + "." + coluna + " ausente");
            } else if (!encontrado.get(0).equals(tipo)) {
                problemas.add(schema + "." + tabela + "." + coluna
                        + " mudou de tipo: esperado " + tipo + ", encontrado " + encontrado.get(0));
            }
        }));
        return problemas;
    }

    private static List<String> dominiosDesconhecidos(JdbcTemplate jdbc, String schema) {
        return jdbc.queryForList("SELECT cd_dominio, cd_valor FROM " + schema + ".de_para_dominio")
                .stream()
                .filter(linha -> {
                    var dominio = (String) linha.get("cd_dominio");
                    var valor = (String) linha.get("cd_valor");
                    var conhecidos = DOMINIOS_CONHECIDOS.get(dominio);
                    return conhecidos == null || !conhecidos.contains(valor);
                })
                .map(linha -> linha.get("cd_dominio") + "=" + linha.get("cd_valor"))
                .toList();
    }

    // -------------------------------------------------------------- colunas

    @Nested
    @DisplayName("8.1 Presenca e tipo das colunas lidas")
    class Colunas {

        @Test
        @DisplayName("o schema de homologacao atende o contrato")
        void schemaAtual() {
            assertThat(divergencias(leitura, "sigh")).isEmpty();
        }

        @Test
        @DisplayName("controle negativo: a verificacao ACUSA uma coluna removida")
        void acusaColunaRemovida() {
            proprietario.execute("DROP SCHEMA IF EXISTS sigh_sem_coluna CASCADE");
            proprietario.execute("CREATE SCHEMA sigh_sem_coluna");
            proprietario.execute("""
                    CREATE TABLE sigh_sem_coluna.paciente AS
                    SELECT cd_paciente, nm_paciente FROM sigh.paciente WITH NO DATA
                    """);

            assertThat(divergencias(proprietario, "sigh_sem_coluna"))
                    .isNotEmpty()
                    .anyMatch(problema -> problema.contains("nr_cpf ausente"));

            proprietario.execute("DROP SCHEMA sigh_sem_coluna CASCADE");
        }

        @Test
        @DisplayName("controle negativo: a verificacao ACUSA uma coluna que trocou de tipo")
        void acusaTipoTrocado() {
            proprietario.execute("DROP SCHEMA IF EXISTS sigh_tipo_trocado CASCADE");
            proprietario.execute("CREATE SCHEMA sigh_tipo_trocado");
            proprietario.execute("""
                    CREATE TABLE sigh_tipo_trocado.paciente (
                      cd_paciente INTEGER, nm_paciente VARCHAR(120), nm_social VARCHAR(120),
                      dt_nascimento DATE, tp_sexo CHAR(1),
                      nr_cpf INTEGER,
                      nr_cns VARCHAR(15), st_ativo CHAR(1), dt_obito DATE,
                      dt_atualizacao TIMESTAMP)
                    """);

            assertThat(divergencias(proprietario, "sigh_tipo_trocado"))
                    .anyMatch(problema -> problema.contains("nr_cpf mudou de tipo"));

            proprietario.execute("DROP SCHEMA sigh_tipo_trocado CASCADE");
        }
    }

    // -------------------------------------------------------------- dominios

    @Nested
    @DisplayName("8.2 Valores de dominio")
    class Dominios {

        @Test
        @DisplayName("nenhum valor de dominio desconhecido pelo codigo")
        void nenhumDesconhecido() {
            assertThat(dominiosDesconhecidos(leitura, "sigh")).isEmpty();
        }

        @Test
        @DisplayName("controle negativo: a verificacao ACUSA um valor novo")
        void acusaValorNovo() {
            proprietario.execute("DROP SCHEMA IF EXISTS sigh_dominio_novo CASCADE");
            proprietario.execute("CREATE SCHEMA sigh_dominio_novo");
            proprietario.execute("""
                    CREATE TABLE sigh_dominio_novo.de_para_dominio AS
                    SELECT * FROM sigh.de_para_dominio
                    """);
            proprietario.update("""
                    INSERT INTO sigh_dominio_novo.de_para_dominio (cd_dominio, cd_valor, ds_valor)
                    VALUES ('SEXO', 'NB', 'Nao binario')
                    """);

            assertThat(dominiosDesconhecidos(proprietario, "sigh_dominio_novo"))
                    .contains("SEXO=NB");

            proprietario.execute("DROP SCHEMA sigh_dominio_novo CASCADE");
        }

        @Test
        @DisplayName("a tabela de dominios do fornecedor NAO cobre o valor 'I' que existe na base")
        void tabelaDeDominiosEstaDesatualizada() {
            var sexosCadastrados = leitura.queryForList(
                    "SELECT cd_valor FROM sigh.de_para_dominio WHERE cd_dominio = 'SEXO'",
                    String.class);
            var sexosEmUso = leitura.queryForList(
                    "SELECT DISTINCT tp_sexo FROM sigh.paciente WHERE tp_sexo IS NOT NULL",
                    String.class);

            // Esta divergencia e o motivo de a fachada NAO ler os dominios desta tabela.
            assertThat(sexosEmUso).contains("I");
            assertThat(sexosCadastrados).doesNotContain("I");
        }
    }

    // ---------------------------------------------------------- categorias

    /**
     * 8.3 — o teste que impede a regressao mais perigosa deste projeto.
     *
     * <p>Se alguem regenerar a base de homologacao sem estas categorias, a suite
     * inteira continua verde e a fachada volta a ser construida sobre a premissa
     * que o levantamento derrubou. Aqui ela fica vermelha.
     */
    @Nested
    @DisplayName("8.3 As categorias dificeis continuam existindo na base")
    class CategoriasDificeis {

        private long contar(String condicao) {
            return leitura.queryForObject(
                    "SELECT count(*) FROM sigh.paciente WHERE " + condicao, Long.class);
        }

        @Test
        @DisplayName("31 pacientes sem CPF — 15,5% da base")
        void semCpf() {
            assertThat(contar("nr_cpf IS NULL")).isEqualTo(31);
        }

        @Test
